using HotChocolate.Types;

namespace Azure.DataApiBuilder.Service.GraphQLBuilder.Directives
{
    /// <summary>
    /// Marks a field the database fills when the client omits it, while still accepting
    /// an explicit value. Distinct from <see cref="AutoGeneratedDirectiveType"/>, which
    /// removes the field from create input.
    /// </summary>
    public class GeneratedByDefaultDirectiveType : DirectiveType
    {
        public static string DirectiveName { get; } = "generatedByDefault";

        protected override void Configure(IDirectiveTypeDescriptor descriptor)
        {
            descriptor
                .Name(DirectiveName)
                .Description("Indicates that the database generates a value when the field is omitted, and that a request may still supply a value.")
                .Location(DirectiveLocation.FieldDefinition);
        }
    }
}
